SELECT Max([Имена-итогов].NAME) AS NAME1, w.OES, w.OBL, o.NAME AS oblname, [Имена-итогов].NUMB1, w.YEAR, Sum(w.NUST) AS NUST, Sum(w.E) AS E, Sum(w.B) AS B, z([int])+z([vork])+z([podm])+z([don])+z([kuzn])+z([sver])+z([chel])+z([kizel])+z([bashk])+z([ekib])+z([karag])+z([nazar])+z([ibor])+z([berez])+z([azey])+z([cher])+z([tuv])+z([hak])+z([gusin])+z([tugn])+z([chit])+z([yakut])+z([prim])+z([luch])+z([amur])+z([urg])+z([mag])+z([sah]) AS ugol, Sum(W!DON/IIf(n.don>0,N!DON,0.699)) AS don, Sum(W!podm/IIf(n.podm>0,N!podm,0.274)) AS podm, z([vork])+z([int]) AS pech, Sum(D!vork/IIf(n.vork>0,N!vork,0.677)) AS vork, Sum(D!int/IIf(n.int>0,N!int,0.532)) AS [int], IIf(W!YEAR<=2000,Sum(W!kuzn/IIf(n.kuzn>0,N!kuzn,0.777)),z([kuznt])+z([kuznss])+z([kuzngd])+z([kuznun])) AS kuzn, Sum(IIf(W!YEAR=2000,0,D!kuznt)/0.81) AS kuznt, Sum(IIf(W!YEAR=2000,0,D!kuznss)/0.803) AS kuznss, Sum(IIf(W!YEAR=2000,0,D!kuzngd)/0.718) AS kuzngd, Sum(IIf(W!YEAR=2000,0,D!kuznun)/0.769) AS kuznun, Sum(D!sver/IIf(N!sver>0,N!sver,0.316)) AS sver, Sum(D!chel/IIf(N!chel>0,N!chel,0.422)) AS chel, Sum(D!kizel/IIf(N!kizel>0,N!kizel,0.624)) AS kizel, Sum(W!bashk/IIf(N!bashk>0,N!bashk,0.29)) AS bashk, Sum(W!ekib/IIf(N!ekib>0,N!ekib,0.551)) AS ekib, Sum(W!karag/IIf(N!karag>0,N!karag,0.502)) AS karag, Sum(D!nazar/IIf(N!nazar>0,N!nazar,0.484)) AS nazar, Sum(D!ibor/IIf(N!ibor>0,N!ibor,0.537)) AS ibor, Sum(D!berez/IIf(N!berez>0,N!berez,0.519)) AS berez, Sum(D!per/IIf(N!per>0,N!per,0.537)) AS per, Sum(D!azey/IIf(N!azey>0,N!azey,0.554)) AS azey, Sum(D!cher/IIf(N!cher>0,N!cher,0.613)) AS cher, Sum(W!hak/IIf(N!hak>0,N!hak,0.656)) AS hak, Sum(W!tuv/IIf(N!tuv>0,N!tuv,0.781)) AS tuv, Sum(D!gusin/IIf(N!gusin>0,N!gusin,0.528)) AS gusin, Sum(D!tugn/IIf(N!tugn>0,N!tugn,0.708)) AS tugn, Sum(W!chit/IIf(N!chit>0,N!chit,0.434)) AS chit, Sum(W!yakut/IIf(N!yakut>0,N!yakut,0.876)) AS yakut, Sum(W!amur/IIf(N!amur>0,N!amur,0.38)) AS amur, Sum(W!urg/IIf(N!urg>0,N!urg,0.645)) AS urg, Sum(W!prim/IIf(N!prim>0,N!prim,0.388)) AS prim, Sum(W!luch/IIf(N!luch>0,N!luch,0.256)) AS luch, Sum(W!mag/IIf(N!mag>0,N!mag,0.64)) AS mag, Sum(W!sah/IIf(N!sah>0,N!sah,0.596)) AS sah, First(e.name) AS oesname
FROM (((([Рабочий(станции)] AS w LEFT JOIN Натура99 AS n ON (w.NUMB1120=n.NUMB1120) AND (w.YEAR=n.YEAR)) INNER JOIN [Имена-итогов] ON w.VED=[Имена-итогов].VED) INNER JOIN Имена_областей AS o ON w.OBL=o.OBL) LEFT JOIN [Рабочий(доп_угли)] AS d ON (w.NUMB1120=d.NUMB1120) AND (w.YEAR=d.YEAR)) INNER JOIN Имена_ОЭС AS e ON w.OES=e.oes
WHERE (((w.VED)>0))
GROUP BY w.OES, w.OBL, o.NAME, [Имена-итогов].NUMB1, w.YEAR
HAVING ((([Имена-итогов].NUMB1)=1) AND ((Sum(w.UGOL))>0))
ORDER BY w.OES, [Имена-итогов].NUMB1, w.YEAR;
